    ; var _g6h_lo =
    ; lo
    LDA _lo
    STX $81
    LDX _lo+1
    STA _g6h_lo
    STX _g6h_lo+1
    ; var _g6h_hi =
    ; hi
    LDA _hi
    LDX _hi+1
