    STX _g6h_hi+1
    ; var _g6h_y =
    ; y
    LDA _y
    LDX _y+1
    STA _g6h_y
    ; var _g6h_p =
    ; pen
    LDA _pen
    STA _g6h_p
    ; var _g6h_sb =
    ; sbase
    LDA _sbase
    LDX _sbase+1
    STA _g6h_sb
    STX _g6h_sb+1
; ptr = sbase+yTable [ y ] .
LDY _g6h_y
CLC
LDA _g6h_sb
ADC _gfx6_yLo,Y
STA _gfx_zp_ptr
LDA _g6h_sb+1
ADC _gfx6_yHi,Y
STA _gfx_zp_ptr+1
; byteL = lo >> 3,iL = lo & 7 .
LDA _g6h_lo+1
LSR A
LDA _g6h_lo
ROR A
LSR A
LSR A
STA _g6h_bL
LDA _g6h_lo
AND #$07
STA _g6h_iL
; byteR = hi >> 3,iR = hi & 7 .
LDA _g6h_hi+1
LSR A
LDA _g6h_hi
ROR A
LSR A
LSR A
STA _g6h_bR
LDA _g6h_hi
AND #$07
STA _g6h_iR
