ORA ( _gfx_zp_ptr ),Y
STA ( _gfx_zp_ptr ),Y
JMP _g6h_done
_g6h_set_multi :
; Left partial ( byteL ) : OR with hLeftSet [ bitL ] .
LDX _g6h_iL
LDY _g6h_bL
LDA ( _gfx_zp_ptr ),Y
ORA _gfx6_hLeftSet,X
STA ( _gfx_zp_ptr ),Y
; Middle bytes : bL+1 ..bR - 1,each byte = $FF .
; Count = bR - bL - 1 ; BEQ skips when adjacent .
INY
LDA _g6h_bR
SEC
SBC _g6h_bL
SEC
SBC #$01
TAX
BEQ _g6h_set_right
LDA #$FF
_g6h_set_mid :
STA ( _gfx_zp_ptr ),Y
INY
DEX
BNE _g6h_set_mid
_g6h_set_right :
; Right partial ( byteR ) : OR with hRightSet [ bitR ] .
LDX _g6h_iR
LDA _gfx6_hRightSet,X
LDY _g6h_bR
ORA ( _gfx_zp_ptr ),Y
STA ( _gfx_zp_ptr ),Y
JMP _g6h_done
; -- -- pen = 0,clear bits -- --
