; Single - byte case : byteL == byteR .
; mask = hLeftSet [ bitL ] AND hRightSet [ bitR ] ; clear = NOT mask .
LDA _g6h_bL
CMP _g6h_bR
BNE _g6h_clr_multi
LDX _g6h_iL
LDA _gfx6_hLeftSet,X
LDX _g6h_iR
AND _gfx6_hRightSet,X
EOR #$FF ; A = clear mask
LDY _g6h_bL
AND ( _gfx_zp_ptr ),Y
STA ( _gfx_zp_ptr ),Y
JMP _g6h_done
_g6h_clr_multi :
; Left partial : AND hLeftClr [ bitL ] with the byte .
LDX _g6h_iL
LDY _g6h_bL
LDA ( _gfx_zp_ptr ),Y
AND _gfx6_hLeftClr,X
STA ( _gfx_zp_ptr ),Y
; Middle bytes : store $00 .
INY
LDA _g6h_bR
SEC
SBC _g6h_bL
SEC
SBC #$01
TAX
BEQ _g6h_clr_right
LDA #$00
_g6h_clr_mid :
STA ( _gfx_zp_ptr ),Y
INY
DEX
BNE _g6h_clr_mid
_g6h_clr_right :
; Right partial : AND hRightClr [ bitR ] with the byte .
LDX _g6h_iR
LDA _gfx6_hRightClr,X
LDY _g6h_bR
AND ( _gfx_zp_ptr ),Y
STA ( _gfx_zp_ptr ),Y
_g6h_done :
