LDA _gfx_zp_mask
ORA ( _gfx_zp_ptr ),Y
STA ( _gfx_zp_ptr ),Y
; ptr+= 20 ( next row )
CLC
LDA _gfx_zp_ptr
ADC #$14
STA _gfx_zp_ptr
