STA _gfx_zp_mask
LDY #$00
_g6v_loop0_top :
LDA _gfx_zp_mask
AND ( _gfx_zp_ptr ),Y
STA ( _gfx_zp_ptr ),Y
CLC
LDA _gfx_zp_ptr
ADC #$14
STA _gfx_zp_ptr
